canary.bend:
law canary_inj_push_without_cf:
  for -X: Type
  for -A: Type
  for -B: Type
  for -h: A -> B
  for -f: X -> A
  for -g: X -> A
  for e: @x:X -> {h(f(x)) == h(g(x)) : B}
  @x:X -> {f(x) == g(x) : A}

laws.bend:
law core_inj_push:
  for -X: Type
  for -A: Type
  for -B: Type
  for -h: A -> B
  for -f: X -> A
  for -g: X -> A
  for cf: @x:X -> {h(f(x)) == h(g(x)) : B} -> {f(x) == g(x) : A}
  for e: @x:X -> {h(f(x)) == h(g(x)) : B}
  @x:X -> {f(x) == g(x) : A}

law core_inj_pull:
  for -X: Type
  for -A: Type
  for -B: Type
  for -h: A -> B
  for -f: X -> A
  for -g: X -> A
  for e: @x:X -> {f(x) == g(x) : A}
  @x:X -> {h(f(x)) == h(g(x)) : B}

law core_cf_succ:
  for x: Nat
  for y: Nat
  for e: {1n+x == 1n+y : Nat}
  {x == y : Nat}
